class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.16.0/commando_0.16.0_darwin_arm64.tar.gz"
      sha256 "9bcf254c07663be39719b0a515cf90c1636466d9681a1e42bff7aa6f0480c18f"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.16.0/commando_0.16.0_darwin_amd64.tar.gz"
      sha256 "f1319b1f299970cf997ad55230ee606dabf7d2a0051112841bfd5973772e046a"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.16.0/commando_0.16.0_linux_arm64.tar.gz"
      sha256 "a0237ed5265276a494004614b09e456e4f5e04cc58ae2583da88a28fe79ac6b5"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.16.0/commando_0.16.0_linux_amd64.tar.gz"
      sha256 "421c31593510b99d946e72decdcbae15cd4fdaf0d6a6480e8dc5409ca9881827"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
